// Necessary eight-port test: maximal blue rows may not miss the same blue seven. A maximal row missing none may repeat in this relaxation.
use std::io::{self,BufRead};
fn clique(cp:&[Vec<u64>],mut o:Vec<u64>,k:u32)->bool{if k==1{return o.iter().any(|&x|x!=0)}let mut n:u32=o.iter().map(|x|x.count_ones()).sum();for w in 0..o.len(){while o[w]!=0{if n<k{return false}let i=w*64+o[w].trailing_zeros()as usize;o[w]&=o[w]-1;n-=1;let next=o.iter().zip(&cp[i]).map(|(x,y)|x&y).collect();if clique(cp,next,k-1){return true}}}false}
fn test(a:[u32;26])->bool{let mut ss=vec![0u32];for i in 0..26{for j in 0..ss.len(){if ss[j]&a[i]==0{ss.push(ss[j]|1<<i)}}}assert!(ss.iter().all(|s|s.count_ones()<8));let rows:Vec<_>=ss.iter().copied().filter(|s|s.count_ones()>=6&&(0..26).all(|j|s&((1<<j)|a[j])!=0)).collect();let n=rows.len();let w=(n+63)/64;let mut cp=vec![vec![u64::MAX;w];n];for q in ss.into_iter().filter(|s|s.count_ones()==7){let miss:Vec<_>=(0..n).filter(|&i|rows[i]&q==0).collect();let mut mask=vec![0;w];for &i in &miss{mask[i/64]|=1u64<<(i%64)}for i in miss{for j in 0..w{cp[i][j]&=!mask[j]}}}if (0..n).any(|i|cp[i][i/64]>>(i%64)&1!=0){return true}let mut o=vec![u64::MAX;w];if n%64!=0{o[w-1]=(1<<(n%64))-1}clique(&cp,o,8)}
fn main(){for l in io::stdin().lock().lines(){let a=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect::<Vec<u32>>().try_into().unwrap();println!("{}",test(a)as u8)}}
